public void SortColors(int[] nums)
{
    int[] count = new int[3];
    foreach (int n in nums) count[n]++;
    int idx = 0;
    for (int c = 0; c < 3; c++)
        for (int i = 0; i < count[c]; i++)
            nums[idx++] = c;
}

public void SortColors(int[] nums)
{
    int low = 0, mid = 0, high = nums.Length - 1;
    while (mid <= high)
    {
        if (nums[mid] == 0)
        {
            (nums[low], nums[mid]) = (nums[mid], nums[low]);
            low++; mid++;
        }
        else if (nums[mid] == 1)
        {
            mid++;
        }
        else
        {
            (nums[mid], nums[high]) = (nums[high], nums[mid]);
            high--;
        }
    }
}
